for(int i=1;i<=N;i++) indeg[A[i]]++;
int *inq=(int*)malloc((size_t)(N+1)*sizeof(int)); int qh=0,qt=0; for(int i=1;i<=N;i++) if(indeg[i]==0) inq[qt++]=i;
int *isCycle=(int*)calloc((size_t)(N+1),sizeof(int));
while(qh<qt){ int v=inq[qh++]; int p=A[v]; indeg[p]--; if(indeg[p]==0) inq[qt++]=p; }
for(int i=1;i<=N;i++) if(indeg[i]>0) isCycle[i]=1;
/* build children list */
int *deg=(int*)calloc((size_t)(N+1),sizeof(int)); for(int i=1;i<=N;i++) if(!isCycle[i]) deg[A[i]]++;
int **child=(int**)malloc((size_t)(N+1)*sizeof(int*)); for(int i=1;i<=N;i++){ child[i]=(deg[i]? (int*)malloc((size_t)deg[i]*sizeof(int)) : NULL); deg[i]=0; }
for(int i=1;i<=N;i++) if(!isCycle[i]) child[A[i]][deg[A[i]]++]=i;
/* dp[node][x] */
long long **dp=(long long**)malloc((size_t)(N+1)*sizeof(long long*));
for(int i=1;i<=N;i++) dp[i]=(long long*)calloc((size_t)(M+1),sizeof(long long));
/* postorder of non-cycle nodes: do simple stack order by topo from leaves */
int *order=(int*)malloc((size_t)(N+1)*sizeof(int)); int ord=0;
for(int i=1;i<=N;i++) if(!isCycle[i]) order[ord++]=i;
for(int idx=ord-1; idx>=0; idx--){ int v=order[idx]; for(int x=1;x<=M;x++){ long long prod=1; for(int k=0;k<deg[v];k++){ int ch=child[v][k]; long long sum=0; for(int t=1;t<=x;t++){ sum=(sum+dp[ch][t])%MOD; } prod=(prod*sum)%MOD; } dp[v][x]=prod; if(deg[v]==0) dp[v][x]=1; } }
long long ans=1;
int *vis=(int*)calloc((size_t)(N+1),sizeof(int));
for(int i=1;i<=N;i++) if(isCycle[i] && !vis[i]){
  /* traverse cycle */
  int v=i; int cyc[3000]; int clen=0; while(!vis[v]){ vis[v]=1; cyc[clen++]=v; v=A[v]; }
  long long comp=0; for(int x=1;x<=M;x++){
    long long prod=1; for(int k=0;k<clen;k++){ int node=cyc[k]; long long sum=1; /* node value fixed x */
      for(int c=0;c<deg[node];c++){ int ch=child[node][c]; long long s=0; for(int t=1;t<=x;t++) s=(s+dp[ch][t])%MOD; sum=(sum*s)%MOD; }
      prod=(prod*sum)%MOD;
    }
    comp=(comp+prod)%MOD;
  }
  ans=(ans*comp)%MOD;
}
return ans;

